#!/usr/bin/env python3
"""Applications of Closure-Extractor Spectrum Duality"""

import itertools
from typing import Callable, Optional

def powerset(ground):
    elems = list(ground)
    result = []
    for r in range(len(elems) + 1):
        for combo in itertools.combinations(elems, r):
            result.append(frozenset(combo))
    return result

def enumerate_closed_sets(ground, cl):
    return sorted([A for A in powerset(ground) if cl(A) == A], key=lambda s: (len(s), sorted(s)))

def find_extremal_witnesses(closed_sets, delta):
    witnesses = []
    for C in closed_sets:
        if not C: continue
        if all(delta(D) < delta(C) for D in closed_sets if D < C):
            witnesses.append(C)
    return witnesses

def build_canonical_extractor(ground, cl, delta):
    closed = enumerate_closed_sets(ground, cl)
    witnesses = find_extremal_witnesses(closed, delta)
    return {
        "num_seeds": len(witnesses),
        "witness_sets": witnesses,
        "defect_bounds": [delta(C) for C in witnesses],
    }

def reconstruct_closure(ground, witness_sets):
    def cl(A):
        covering = [W for W in witness_sets if A <= W]
        if covering:
            result = covering[0]
            for W in covering[1:]: result = result & W
            return result
        return ground
    return cl

