ground = frozenset({0, 1, 2, 3, 4})
def cl1(A):
    result = set(A)
    changed = True
    while changed:
        changed = False
        if 0 in result and 1 not in result: result.add(1); changed = True
        if 1 in result and 0 not in result: result.add(0); changed = True
        if 3 in result and 4 in result and 2 not in result: result.add(2); changed = True
    return frozenset(result)

def delta1(A):
    clA = cl1(A)
    if not clA: return 0
    dep_groups = 0
    if clA & {0, 1}: dep_groups += 1
    if clA & {3, 4}: dep_groups += 1
    return dep_groups

ext = build_canonical_extractor(ground, cl1, delta1)
print(f"Sensor array: {{s0, s1, s2, s3, s4}}")
print(f"Dependencies: s0 <-> s1, s3+s4 -> s2")
print(f"Spectrum rank (min seeds): {ext['num_seeds']}")
print(f"Extremal witnesses: {[set(C) for C in ext['witness_sets']]}")

