ground2 = frozenset({0, 1, 2, 3})
def cl2(A):
    result = set(A)
    if 0 in result and 1 in result: result.add(3)
    return frozenset(result)
def delta2(A):
    clA = cl2(A)
    if not clA: return 0
    return sum(1 for x in [0,1,2] if x in clA)

ext2 = build_canonical_extractor(ground2, cl2, delta2)
print(f"Features: {{f0, f1, f2, f3}}, f3=f(f0,f1)")
print(f"Spectrum rank: {ext2['num_seeds']}")
print(f"Extremal witnesses: {[set(C) for C in ext2['witness_sets']]}")

