ground3 = frozenset({0, 1, 2, 3})
chain = [frozenset(), frozenset({0}), frozenset({0,1}), frozenset({0,1,2}), ground3]
def cl_chain(A):
    for C in chain:
        if A <= C: return C
    return ground3
def delta_chain(A):
    return chain.index(cl_chain(A))

ext3 = build_canonical_extractor(ground3, cl_chain, delta_chain)
print(f"Chain closure: spectrum rank = {ext3['num_seeds']}")

def cl_part(A):
    if not A: return frozenset()
    if A <= frozenset({0,1}): return frozenset({0,1})
    if A <= frozenset({2,3}): return frozenset({2,3})
    return ground3
def delta_part(A):
    clA = cl_part(A)
    if not clA: return 0
    return sum(1 for b in [{0,1},{2,3}] if clA & b)
ext4 = build_canonical_extractor(ground3, cl_part, delta_part)
print(f"Partition closure: spectrum rank = {ext4['num_seeds']}")

def cl_full(A):
    return ground3 if A else frozenset()
def delta_full(A):
    return 1 if cl_full(A) else 0
ext5 = build_canonical_extractor(ground3, cl_full, delta_full)
print(f"Full closure: spectrum rank = {ext5['num_seeds']}")
print()
